class Solution {
public:
    PolyNode* addPoly(PolyNode* poly1, PolyNode* poly2) {
        PolyNode dummy(0, 0);
        PolyNode* tail = &dummy;
        while (poly1 || poly2) {
            int power, coefficient;
            if (!poly2 || (poly1 && poly1->power > poly2->power)) {
                power = poly1->power; coefficient = poly1->coefficient;
                poly1 = poly1->next;
            } else if (!poly1 || poly2->power > poly1->power) {
                power = poly2->power; coefficient = poly2->coefficient;
                poly2 = poly2->next;
            } else {
                power = poly1->power;
                coefficient = poly1->coefficient + poly2->coefficient;
                poly1 = poly1->next; poly2 = poly2->next;
            }
            if (coefficient != 0) {
                tail->next = new PolyNode(coefficient, power);
                tail = tail->next;
            }
        }
        return dummy.next;
    }
};
